/**
 * Server-side Appwrite (TablesDB) client — replaces the Supabase service-role
 * client for every route that has been migrated.
 *
 * Server-side ONLY: APPWRITE_API_KEY bypasses row permissions.
 *
 * Table IDs are generated by Appwrite (e.g. "6aeeff03001e1602ebac"), not the
 * table names, so they are resolved by name once per process and cached.
 */

import { Client, TablesDB, Query, ID, AppwriteException } from 'node-appwrite'

export { Query, ID, AppwriteException }

const REQUIRED = ['APPWRITE_ENDPOINT', 'APPWRITE_PROJECT_ID', 'APPWRITE_API_KEY', 'APPWRITE_DATABASE_ID']

let db = null

/**
 * Lazily built so a missing env var fails the request that needs Appwrite
 * (with a clear message) instead of crashing the whole server at boot.
 */
export function tablesDB() {
  if (db) return db
  const missing = REQUIRED.filter((k) => !process.env[k])
  if (missing.length) throw new Error(`Appwrite not configured: missing ${missing.join(', ')}`)

  const client = new Client()
    .setEndpoint(process.env.APPWRITE_ENDPOINT)
    .setProject(process.env.APPWRITE_PROJECT_ID)
    .setKey(process.env.APPWRITE_API_KEY.trim())
  db = new TablesDB(client)
  return db
}

/**
 * Safe diagnostic for /health: which env vars are missing and whether a real
 * Appwrite read works. Never returns values, only names and error codes.
 */
export async function appwriteStatus() {
  const missing = REQUIRED.filter((k) => !process.env[k]?.trim())
  if (missing.length) return { ok: false, missing }
  try {
    const ids = await tablesDB().listTables({ databaseId: databaseId(), queries: [Query.limit(100)] })
    return { ok: true, tables: ids.tables.length }
  } catch (err) {
    return { ok: false, code: err.code ?? null, type: err.type ?? err.name, message: err.message }
  }
}

export function databaseId() {
  return process.env.APPWRITE_DATABASE_ID
}

let tableIdsPromise = null

/** Resolve a table name (e.g. 'memes') to its Appwrite table ID. */
export async function tableId(name) {
  tableIdsPromise ??= tablesDB()
    .listTables({ databaseId: databaseId(), queries: [Query.limit(100)] })
    .then(({ tables }) => Object.fromEntries(tables.map((t) => [t.name, t.$id])))
    .catch((err) => {
      tableIdsPromise = null // retry next call instead of caching the failure
      throw err
    })

  const ids = await tableIdsPromise
  if (!ids[name]) throw new Error(`Appwrite table "${name}" not found`)
  return ids[name]
}

/**
 * Appwrite row → the plain shape the app used with Supabase: `$id` becomes
 * `id`, and Appwrite's own `$…` metadata is dropped.
 */
export function toPlain(row) {
  if (!row) return row
  const out = { id: row.$id }
  for (const [k, v] of Object.entries(row)) {
    if (!k.startsWith('$')) out[k] = v
  }
  return out
}

/** One page of rows from a table, as plain objects. */
export async function listRows(table, queries = []) {
  const res = await tablesDB().listRows({
    databaseId: databaseId(),
    tableId: await tableId(table),
    queries,
  })
  return { rows: res.rows.map(toPlain), total: res.total }
}

/**
 * Every row matching `queries`, paged by cursor. Appwrite caps `total` at
 * 5000, so large tables (download_events) must be counted by paging.
 */
export async function listAllRows(table, queries = [], { pageSize = 1000, cap = 100_000 } = {}) {
  const tid = await tableId(table)
  const out = []
  let cursor = null

  while (out.length < cap) {
    const page = [...queries, Query.limit(Math.min(pageSize, cap - out.length))]
    if (cursor) page.push(Query.cursorAfter(cursor))

    const { rows } = await tablesDB().listRows({ databaseId: databaseId(), tableId: tid, queries: page })
    if (!rows.length) break
    out.push(...rows.map(toPlain))
    cursor = rows[rows.length - 1].$id
    if (rows.length < pageSize) break
  }
  return out
}

/** A single row by ID, or null when it does not exist. */
export async function getRow(table, rowId, queries) {
  try {
    const row = await tablesDB().getRow({
      databaseId: databaseId(),
      tableId: await tableId(table),
      rowId,
      ...(queries ? { queries } : {}),
    })
    return toPlain(row)
  } catch (err) {
    if (err instanceof AppwriteException && err.code === 404) return null
    throw err
  }
}

export async function createRow(table, data, rowId = ID.unique()) {
  const row = await tablesDB().createRow({
    databaseId: databaseId(),
    tableId: await tableId(table),
    rowId,
    data,
  })
  return toPlain(row)
}

export async function incrementColumn(table, rowId, column, value = 1) {
  const row = await tablesDB().incrementRowColumn({
    databaseId: databaseId(),
    tableId: await tableId(table),
    rowId,
    column,
    value,
  })
  return toPlain(row)
}
